add_action( 'init', 'perfectpixel_tax_display_switch_handle' );
add_filter( 'pre_option_woocommerce_tax_display_shop', 'perfectpixel_tax_display_choice' );
add_filter( 'pre_option_woocommerce_tax_display_cart', 'perfectpixel_tax_display_choice' );
add_shortcode( 'tax_display_switcher', 'perfectpixel_tax_display_switcher' );

function perfectpixel_tax_display_switch_handle() {
	if ( isset( $_GET['tax_display'] ) && in_array( $_GET['tax_display'], array( 'incl', 'excl' ), true ) && ! is_admin() ) {
		$value = sanitize_key( $_GET['tax_display'] );
		setcookie( 'perfectpixel_tax_display', $value, time() + 30 * DAY_IN_SECONDS, COOKIEPATH, COOKIE_DOMAIN, is_ssl(), true );
		$_COOKIE['perfectpixel_tax_display'] = $value;
		wp_safe_redirect( remove_query_arg( 'tax_display' ) );
		exit;
	}
}

function perfectpixel_tax_display_choice( $value ) {
	if ( is_admin() && ! wp_doing_ajax() ) {
		return $value;
	}
	$choice = isset( $_COOKIE['perfectpixel_tax_display'] ) ? sanitize_key( $_COOKIE['perfectpixel_tax_display'] ) : '';
	return in_array( $choice, array( 'incl', 'excl' ), true ) ? $choice : $value;
}

function perfectpixel_tax_display_switcher() {
	$current = get_option( 'woocommerce_tax_display_shop' );
	$links   = array();
	foreach ( array( 'incl' => '{{tax_switch_incl_label}}', 'excl' => '{{tax_switch_excl_label}}' ) as $key => $label ) {
		$links[] = $key === $current
			? '<strong>' . esc_html( $label ) . '</strong>'
			: '<a href="' . esc_url( add_query_arg( 'tax_display', $key ) ) . '" rel="nofollow">' . esc_html( $label ) . '</a>';
	}
	return '<span class="perfectpixel-tax-switcher">' . implode( ' | ', $links ) . '</span>';
}
